files.content:
body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 0;
    background-color: #f9f9f9;
}

.container {
    max-width: 600px;
    margin: 50px auto;
    padding: 20px;
    background-color: #ffffff;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
    border-radius: 8px;
}

h1, h2 {
    color: #333333;
    text-align: center;
}

#note-form {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

#note-content {
    width: 100%;
    height: 100px;
    padding: 10px;
    border: 1px solid #cccccc;
    border-radius: 4px;
    font-size: 16px;
}

button {
    padding: 10px 20px;
    background-color: #007BFF;
    color: #ffffff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 16px;
}

button:hover {
    background-color: #0056b3;
}

#notes-container {
    margin-top: 20px;
}

#notes-list {
    list-style-type: none;
    padding: 0;
}

#notes-list li {
    padding: 10px;
    border-bottom: 1px solid #eeeeee;
}

#notes-list li:last-child {
    border-bottom: none;
}
